/* ---------- Constantes ---------- */
const ETAPAS = ['Consulta', 'Planejamento', 'Atendimento', 'Pós-atendimento', 'Retorno', 'Finalizado'];
const MESES = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const DIAS_SEMANA = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];
const DIAS_SEMANA_EXTENSO = ['Domingo', 'Segunda-feira', 'Terça-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira', 'Sábado'];
const IMPOSTO_NF = 0.06;

const STATUS = {
  pre_reserva: { label: 'Pré Reserva', color: '#A89B8C' },
  confirmado: { label: 'Confirmado', color: '#C39B99' },
  aguardando_pagamento: { label: 'Aguardando pagamento', color: '#8C8478' },
  atrasado: { label: 'Pagamento em atraso', color: '#B4483D' },
  concluido: { label: 'Concluído', color: '#4C7A5E' },
};

// Só estas ficam disponíveis pra escolha manual — "Pagamento em atraso" é
// calculado automaticamente, e "Concluído" só acontece quando o pagamento é feito.
const STATUS_SELECIONAVEIS = {
  pre_reserva: STATUS.pre_reserva,
  confirmado: STATUS.confirmado,
  aguardando_pagamento: STATUS.aguardando_pagamento,
};

// Calcula o status "de verdade" de um atendimento: se est\u00e1 aguardando
// pagamento e alguma parcela ligada a ele j\u00e1 passou da data sem ser paga,
// vira "atrasado".
function statusExibicaoChave(demanda, financas) {
  if (demanda.status === 'aguardando_pagamento') {
    const temAtraso = financas.some(
      (f) => f.origemDemandaId === demanda.id && !f.pago && diasRestantes(f.dataPagamento) < 0
    );
    if (temAtraso) return 'atrasado';
  }
  return demanda.status;
}

const SERVICOS = ['Curso de Penteados', 'Penteado Social', 'Noiva', 'Teste de Noiva', 'Penteado Debutante'];

const STATUS_FIN = {
  pago: { label: 'Pago', color: '#4C7A5E' },
  pendente: { label: 'Pendente', color: '#C39B99' },
  atrasado: { label: 'Atrasado', color: '#B4483D' },
};

const TIPO_EVENTO = {
  briefing: { label: 'Consulta', color: '#A89B8C' },
  gravacao: { label: 'Atendimento', color: '#C39B99' },
  entrega: { label: 'Finalizado', color: '#B4483D' },
  pagamento: { label: 'Pagamento', color: '#4C7A5E' },
};
