/* ---------- Dados ---------- */
const seedDemandas = [];

const seedFinancas = [];

const seedGastos = [];

const HOJE = new Date();
const URL_EMISSOR_NF = 'https://www.nfse.gov.br/EmissorNacional/Login?ReturnUrl=%2fEmissorNacional%2fDPS%2fPessoas';
HOJE.setHours(0, 0, 0, 0);
const moeda = (v) => v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

function diasRestantes(data) {
  return Math.round((new Date(data + 'T00:00:00') - HOJE) / 86400000);
}
function prazoLabel(dias) {
  if (dias < 0) return `Atrasado há ${Math.abs(dias)} dia${Math.abs(dias) === 1 ? '' : 's'}`;
  if (dias === 0) return 'Hoje';
  if (dias === 1) return 'Amanhã';
  return `Faltam ${dias} dias`;
}
function gerarDias(ano, mes) {
  const primeiro = new Date(ano, mes, 1);
  const ultimo = new Date(ano, mes + 1, 0);
  const dias = [];
  for (let i = 0; i < primeiro.getDay(); i++) dias.push(null);
  for (let d = 1; d <= ultimo.getDate(); d++) dias.push(new Date(ano, mes, d));
  return dias;
}
function chaveData(d) { return d.toISOString().slice(0, 10); }
function corTexto(hex) {
  const c = (hex || '#FAF8F5').replace('#', '');
  const r = parseInt(c.substring(0, 2), 16), g = parseInt(c.substring(2, 4), 16), b = parseInt(c.substring(4, 6), 16);
  const luminancia = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminancia > 0.6 ? '#2B2724' : '#FFFFFF';
}
function ordenarEventosDia(eventos) {
  return [...eventos].sort((a, b) => {
    const ta = a.diaTodo === false ? (a.horaInicio || '23:59') : '00:00';
    const tb = b.diaTodo === false ? (b.horaInicio || '23:59') : '00:00';
    return ta.localeCompare(tb);
  });
}
function statusFinanceiro(f) {
  if (f.pago) return 'pago';
  return diasRestantes(f.dataPagamento) < 0 ? 'atrasado' : 'pendente';
}
function valorLiquidoTrabalho(bruto, comNF) { return comNF ? bruto * (1 - IMPOSTO_NF) : bruto; }
function mesChave(data) {
  const d = new Date(data + 'T00:00:00');
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}
function mesLabelCurto(chave) {
  const [ano, mes] = chave.split('-');
  return `${MESES[Number(mes) - 1].slice(0, 3).toUpperCase()}/${ano.slice(2)}`;
}

function mapDemandaDoBanco(row) {
  return {
    id: row.id,
    cliente: row.cliente,
    projeto: row.projeto,
    etapa: row.etapa,
    prazo: row.prazo,
    horario: row.horario || '',
    status: row.status,
    dataGravacao: row.data_gravacao,
    datasGravacao: row.datas_gravacao || [],
    descricao: row.descricao || '',
    endereco: row.endereco || '',
    noEstudio: row.no_estudio || false,
    quantidadePessoas: row.quantidade_pessoas || 1,
    valor: Number(row.valor),
    comNF: row.com_nf,
  };
}
function mapFinancaDoBanco(row) {
  return {
    id: row.id,
    cliente: row.cliente,
    projeto: row.projeto,
    valor: Number(row.valor),
    valorBruto: row.valor_bruto != null ? Number(row.valor_bruto) : Number(row.valor),
    comNF: row.com_nf,
    dataTrabalho: row.data_trabalho,
    dataPagamento: row.data_pagamento,
    pago: row.pago,
    origemDemandaId: row.origem_demanda_id,
    parcelaNumero: row.parcela_numero || 1,
    parcelaTotal: row.parcela_total || 1,
    grupoParcelamento: row.grupo_parcelamento || null,
  };
}
function mapGastoDoBanco(row) {
  return {
    id: row.id,
    projeto: row.projeto,
    cliente: row.cliente,
    descricao: row.descricao,
    valor: Number(row.valor),
    data: row.data,
  };
}

const emptyDemanda = { cliente: '', projeto: '', etapa: ETAPAS[0], prazo: '', horario: '', status: 'pre_reserva', dataGravacao: null, datasGravacao: [], descricao: '', endereco: '', noEstudio: false, quantidadePessoas: 1, valor: '', comNF: false, dataPagamento: '', parcelado: false, parcelas: [] };
const emptyFinanca = { cliente: '', projeto: '', valor: '', dataTrabalho: '', dataPagamento: '', pago: false, parcelado: false, parcelas: [] };
const emptyGasto = { projeto: '', cliente: '', descricao: '', valor: '', data: '' };

function gerarParcelamento(form, quantidade) {
  const qtd = Math.max(2, Number(quantidade) || 2);
  const valorTotal = Number(form.valor) || 0;
  const valorParcela = qtd > 0 ? Math.round((valorTotal / qtd) * 100) / 100 : 0;
  const dataBase = form.dataPagamento ? new Date(form.dataPagamento + 'T00:00:00') : new Date();
  const parcelas = Array.from({ length: qtd }, (_, i) => {
    if (form.parcelas[i]) return form.parcelas[i];
    const data = new Date(dataBase);
    data.setMonth(data.getMonth() + i);
    return { valor: valorParcela, data: data.toISOString().slice(0, 10) };
  });
  return { ...form, parcelado: true, parcelas };
}

/* ---------- Campos reutilizáveis de parcelamento ---------- */
function CamposParcelamento({ form, setForm }) {
  return (
    <>
      <label className="flex items-center gap-2 text-sm mono" style={{ color: '#8C8478' }}>
        <input
          type="checkbox"
          checked={form.parcelado}
          onChange={(e) => {
            if (e.target.checked) setForm(gerarParcelamento(form, 2));
            else setForm({ ...form, parcelado: false, parcelas: [] });
          }}
          style={{ accentColor: '#C39B99' }}
        />
        Pagamento parcelado?
      </label>
      {form.parcelado && (
        <div className="flex flex-col gap-2 rounded p-3" style={{ border: '1px solid #E8E3DC' }}>
          <div className="flex flex-col gap-1">
            <span className="mono text-[11px]" style={{ color: '#8C8478' }}>QUANTIDADE DE PARCELAS</span>
            <input
              type="number"
              min={2}
              value={form.parcelas.length}
              onChange={(e) => setForm(gerarParcelamento(form, e.target.value))}
              className="focusable rounded px-3 py-2 text-sm"
            />
          </div>
          {form.parcelas.map((p, idx) => (
            <div key={idx} className="grid grid-cols-2 gap-2">
              <div className="flex flex-col gap-1">
                <span className="mono text-[10px]" style={{ color: '#8C8478' }}>PARCELA {idx + 1} · DATA</span>
                <input
                  type="date"
                  value={p.data}
                  onChange={(e) => {
                    const novas = form.parcelas.map((item, i) => (i === idx ? { ...item, data: e.target.value } : item));
                    setForm({ ...form, parcelas: novas });
                  }}
                  className="focusable rounded px-3 py-2 text-sm"
                />
              </div>
              <div className="flex flex-col gap-1">
                <span className="mono text-[10px]" style={{ color: '#8C8478' }}>VALOR</span>
                <input
                  type="number"
                  value={p.valor}
                  onChange={(e) => {
                    const novas = form.parcelas.map((item, i) => (i === idx ? { ...item, valor: e.target.value } : item));
                    setForm({ ...form, parcelas: novas });
                  }}
                  className="focusable rounded px-3 py-2 text-sm"
                />
              </div>
            </div>
          ))}
          <div className="mono text-[11px]" style={{ color: '#8C8478' }}>
            Soma das parcelas: {moeda(form.parcelas.reduce((s, p) => s + (Number(p.valor) || 0), 0))}
          </div>
        </div>
      )}
    </>
  );
}


/* ---------- Tela: Login ---------- */
function TelaLogin() {
  const [modo, setModo] = useState('entrar'); // 'entrar' | 'cadastrar'
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [erro, setErro] = useState('');
  const [mensagem, setMensagem] = useState('');
  const [carregando, setCarregando] = useState(false);

  async function enviar(e) {
    e.preventDefault();
    setErro('');
    setMensagem('');
    setCarregando(true);

    if (modo === 'entrar') {
      const { error } = await supabase.auth.signInWithPassword({ email, password: senha });
      if (error) setErro(error.message === 'Invalid login credentials' ? 'E-mail ou senha incorretos.' : error.message);
    } else {
      const { data, error } = await supabase.auth.signUp({ email, password: senha });
      if (error) {
        setErro(error.message);
      } else if (data.user && !data.session) {
        setMensagem('Conta criada! Verifique seu e-mail para confirmar antes de entrar.');
      }
    }
    setCarregando(false);
  }

  return (
    <div style={{ background: '#FAF8F5', minHeight: '100vh', color: '#2B2724', fontFamily: "'Inter', sans-serif" }} className="flex items-center justify-center p-5">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Inter:wght@400;500;600;700&display=swap');
        .mono { font-family: 'Manrope', monospace; }
        input { background: #FFFFFF; border: 1px solid #E8E3DC; color: #2B2724; font-family: 'Inter', sans-serif; }
        input:focus { outline: 2px solid #C39B99; outline-offset: 1px; }
        .focusable:focus-visible { outline: 2px solid #C39B99; outline-offset: 2px; }
      `}</style>
      <form onSubmit={enviar} className="w-full max-w-xs rounded-lg p-6" style={{ background: '#FFFFFF', border: '1px solid #E8E3DC' }}>
        <div className="flex flex-col items-center gap-3 mb-6">
          <img src={LOGO_SRC} alt="Pâmela Mees Penteados" style={{ width: 64, height: 64, borderRadius: '9999px', objectFit: 'cover' }} />
          <div className="text-center">
            <div className="mono text-xs tracking-widest" style={{ color: '#8C8478' }}>PAINEL DE ATENDIMENTOS</div>
            <h1 className="mono text-lg font-semibold">Pâmela Mees Penteados</h1>
          </div>
        </div>

        <div className="flex gap-1 p-1 rounded mb-4" style={{ background: '#F1EBE4', border: '1px solid #E8E3DC' }}>
          <button
            type="button"
            onClick={() => { setModo('entrar'); setErro(''); setMensagem(''); }}
            className="flex-1 mono text-xs font-semibold py-1.5 rounded"
            style={{ background: modo === 'entrar' ? '#C39B99' : 'transparent', color: modo === 'entrar' ? '#2B2724' : '#8C8478' }}
          >
            Entrar
          </button>
          <button
            type="button"
            onClick={() => { setModo('cadastrar'); setErro(''); setMensagem(''); }}
            className="flex-1 mono text-xs font-semibold py-1.5 rounded"
            style={{ background: modo === 'cadastrar' ? '#C39B99' : 'transparent', color: modo === 'cadastrar' ? '#2B2724' : '#8C8478' }}
          >
            Criar conta
          </button>
        </div>

        <div className="flex flex-col gap-3">
          <input required type="email" placeholder="E-mail" value={email} onChange={(e) => setEmail(e.target.value)} className="focusable rounded px-3 py-2 text-sm" />
          <input required type="password" placeholder="Senha (mín. 6 caracteres)" value={senha} onChange={(e) => setSenha(e.target.value)} minLength={6} className="focusable rounded px-3 py-2 text-sm" />
          {erro && <p className="mono text-xs" style={{ color: '#B4483D' }}>{erro}</p>}
          {mensagem && <p className="mono text-xs" style={{ color: '#4C7A5E' }}>{mensagem}</p>}
          <button type="submit" disabled={carregando} className="focusable mono text-sm font-semibold rounded py-2 mt-1" style={{ background: '#C39B99', color: '#2B2724', opacity: carregando ? 0.6 : 1 }}>
            {carregando ? 'Aguarde...' : modo === 'entrar' ? 'Entrar' : 'Criar conta'}
          </button>
        </div>
      </form>
    </div>
  );
}

/* ---------- App ---------- */
export default function App() {
  const [aba, setAba] = useState('demandas');
  const [demandas, setDemandas] = useState(seedDemandas);
  const [financas, setFinancas] = useState(seedFinancas);
  const [gastos, setGastos] = useState(seedGastos);
  const [carregado, setCarregado] = useState(false);
  const [session, setSession] = useState(null);
  const [authCarregado, setAuthCarregado] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      setSession(data.session);
      setAuthCarregado(true);
    });
    const { data: listener } = supabase.auth.onAuthStateChange((_evento, novaSessao) => {
      setSession(novaSessao);
    });
    return () => listener.subscription.unsubscribe();
  }, []);

  async function handleLogout() {
    await supabase.auth.signOut();
  }

  function baixarBackupCompleto() {
    const dados = {
      geradoEm: new Date().toISOString(),
      demandas,
      financas,
      gastos,
    };
    const blob = new Blob([JSON.stringify(dados, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup-pamela-mees-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  const [erroConexao, setErroConexao] = useState(false);

  async function carregarTudo() {
    try {
      const [{ data: d, error: ed }, { data: f, error: ef }, { data: g, error: eg }] = await Promise.all([
        supabase.from('demandas').select('*').order('prazo', { ascending: true }),
        supabase.from('financas').select('*').order('data_pagamento', { ascending: true }),
        supabase.from('gastos').select('*').order('data', { ascending: true }),
      ]);
      if (ed || ef || eg) throw ed || ef || eg;
      setDemandas((d || []).map(mapDemandaDoBanco));
      setFinancas((f || []).map(mapFinancaDoBanco));
      setGastos((g || []).map(mapGastoDoBanco));
      setErroConexao(false);
    } catch (e) {
      console.error('Erro ao carregar dados do Supabase:', e);
      setErroConexao(true);
    } finally {
      setCarregado(true);
    }
  }

  useEffect(() => {
    if (!session || !supabaseConfigurado) return;
    carregarTudo();

    // Sincronização em tempo real: quando qualquer aparelho muda algo,
    // todos os outros recarregam os dados automaticamente.
    const canal = supabase
      .channel('painel-realtime')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'demandas' }, carregarTudo)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'financas' }, carregarTudo)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'gastos' }, carregarTudo)
      .subscribe();

    return () => { supabase.removeChannel(canal); };
  }, [session]);

  // Backup diário: sempre que o app é aberto num dia novo, salva uma
  // "fotografia" de todos os dados no banco, substituindo a do dia anterior.
  useEffect(() => {
    if (!session || !carregado) return;
    salvarBackupDiario();
    atualizarStatusPorAtendimentoPassado();
  }, [session, carregado]);

  async function salvarBackupDiario() {
    try {
      const hoje = new Date();
      const dataRef = `${hoje.getFullYear()}-${String(hoje.getMonth() + 1).padStart(2, '0')}-${String(hoje.getDate()).padStart(2, '0')}`;
      const dados = { demandas, financas, gastos, geradoEm: new Date().toISOString() };
      const { error } = await supabase
        .from('agenda_backups')
        .upsert({ user_id: session.user.id, data_referencia: dataRef, dados }, { onConflict: 'user_id,data_referencia' });
      if (error) console.error('Erro ao salvar backup diário:', error);
    } catch (e) {
      console.error('Erro ao salvar backup diário:', e);
    }
  }

  // Assim que o dia do atendimento passa, o atendimento sai de "Confirmado" e
  // vai automaticamente para "Aguardando pagamento".
  async function atualizarStatusPorAtendimentoPassado() {
    try {
      const pendentes = demandas.filter((d) => {
        if (d.etapa !== 'Atendimento' || d.status !== 'confirmado') return false;
        const datas = (d.datasGravacao && d.datasGravacao.length > 0) ? d.datasGravacao : [d.dataGravacao || d.prazo];
        const ultimaData = datas.filter(Boolean).sort().slice(-1)[0];
        return ultimaData && diasRestantes(ultimaData) < 0;
      });
      if (pendentes.length === 0) return;
      const { error } = await supabase
        .from('demandas')
        .update({ status: 'aguardando_pagamento' })
        .in('id', pendentes.map((d) => d.id));
      if (error) { console.error('Erro ao atualizar status pós-atendimento:', error); return; }
      carregarTudo();
    } catch (e) {
      console.error('Erro ao atualizar status pós-atendimento:', e);
    }
  }

  async function criarDemanda(form) {
    const valorBruto = Number(form.valor);
    const { data: demandaInserida, error: erroDemanda } = await supabase
      .from('demandas')
      .insert({
        cliente: form.cliente,
        projeto: form.projeto,
        etapa: form.etapa,
        prazo: form.prazo,
        horario: form.horario || null,
        status: form.status,
        data_gravacao: form.dataGravacao || null,
        datas_gravacao: form.etapa === 'Atendimento' ? (form.datasGravacao || []) : [],
        descricao: form.descricao || '',
        endereco: form.noEstudio ? '' : (form.endereco || ''),
        no_estudio: form.noEstudio,
        quantidade_pessoas: Number(form.quantidadePessoas) || 1,
        valor: valorBruto,
        com_nf: form.comNF,
      })
      .select()
      .single();
    if (erroDemanda) { alert('Erro ao salvar o atendimento: ' + erroDemanda.message); return; }

    if (form.parcelado && form.parcelas.length > 1) {
      const grupoId = crypto.randomUUID();
      const linhas = form.parcelas.map((p, idx) => {
        const bruto = Number(p.valor);
        return {
          cliente: form.cliente,
          projeto: form.projeto,
          valor: valorLiquidoTrabalho(bruto, form.comNF),
          valor_bruto: bruto,
          com_nf: form.comNF,
          data_trabalho: form.prazo,
          data_pagamento: p.data,
          pago: false,
          origem_demanda_id: demandaInserida.id,
          parcela_numero: idx + 1,
          parcela_total: form.parcelas.length,
          grupo_parcelamento: grupoId,
        };
      });
      const { error: erroFinanca } = await supabase.from('financas').insert(linhas);
      if (erroFinanca) alert('Atendimento salvo, mas houve um erro ao lançar as parcelas no financeiro: ' + erroFinanca.message);
      carregarTudo();
      return;
    }

    const valorLiquido = valorLiquidoTrabalho(valorBruto, form.comNF);
    const { error: erroFinanca } = await supabase.from('financas').insert({
      cliente: form.cliente,
      projeto: form.projeto,
      valor: valorLiquido,
      valor_bruto: valorBruto,
      com_nf: form.comNF,
      data_trabalho: form.prazo,
      data_pagamento: form.dataPagamento || form.prazo,
      pago: false,
      origem_demanda_id: demandaInserida.id,
      parcela_numero: 1,
      parcela_total: 1,
    });
    if (erroFinanca) alert('Atendimento salvo, mas houve um erro ao lançar no financeiro: ' + erroFinanca.message);
    carregarTudo();
  }

  async function excluirDemanda(demanda) {
    const { error } = await supabase.from('demandas').delete().eq('id', demanda.id);
    if (error) { alert('Erro ao excluir: ' + error.message); return; }
    carregarTudo();
  }

  async function atualizarDemanda(id, form) {
    const valorBruto = Number(form.valor);
    const { error: erroDemanda } = await supabase
      .from('demandas')
      .update({
        cliente: form.cliente,
        projeto: form.projeto,
        etapa: form.etapa,
        prazo: form.prazo,
        horario: form.horario || null,
        status: form.status,
        data_gravacao: form.dataGravacao || null,
        datas_gravacao: form.etapa === 'Atendimento' ? (form.datasGravacao || []) : [],
        descricao: form.descricao || '',
        endereco: form.noEstudio ? '' : (form.endereco || ''),
        no_estudio: form.noEstudio,
        quantidade_pessoas: Number(form.quantidadePessoas) || 1,
        valor: valorBruto,
        com_nf: form.comNF,
      })
      .eq('id', id);
    if (erroDemanda) { alert('Erro ao atualizar o atendimento: ' + erroDemanda.message); return; }

    const { data: antigas } = await supabase.from('financas').select('parcela_numero, pago').eq('origem_demanda_id', id);
    const pagoPorParcela = {};
    (antigas || []).forEach((f) => { pagoPorParcela[f.parcela_numero || 1] = f.pago; });

    const { error: erroApagar } = await supabase.from('financas').delete().eq('origem_demanda_id', id);
    if (erroApagar) { alert('Erro ao atualizar o lançamento financeiro: ' + erroApagar.message); return; }

    if (form.parcelado && form.parcelas.length > 1) {
      const grupoId = crypto.randomUUID();
      const linhas = form.parcelas.map((p, idx) => {
        const bruto = Number(p.valor);
        return {
          cliente: form.cliente,
          projeto: form.projeto,
          valor: valorLiquidoTrabalho(bruto, form.comNF),
          valor_bruto: bruto,
          com_nf: form.comNF,
          data_trabalho: form.prazo,
          data_pagamento: p.data,
          pago: pagoPorParcela[idx + 1] || false,
          origem_demanda_id: id,
          parcela_numero: idx + 1,
          parcela_total: form.parcelas.length,
          grupo_parcelamento: grupoId,
        };
      });
      const { error: erroFinanca } = await supabase.from('financas').insert(linhas);
      if (erroFinanca) alert('Atendimento atualizado, mas houve um erro ao lançar as parcelas no financeiro: ' + erroFinanca.message);
      carregarTudo();
      return;
    }

    const valorBrutoUnico = Number(form.valor);
    const { error: erroFinanca } = await supabase.from('financas').insert({
      cliente: form.cliente,
      projeto: form.projeto,
      valor: valorLiquidoTrabalho(valorBrutoUnico, form.comNF),
      valor_bruto: valorBrutoUnico,
      com_nf: form.comNF,
      data_trabalho: form.prazo,
      data_pagamento: form.dataPagamento || form.prazo,
      pago: pagoPorParcela[1] || false,
      origem_demanda_id: id,
      parcela_numero: 1,
      parcela_total: 1,
    });
    if (erroFinanca) alert('Atendimento atualizado, mas houve um erro ao atualizar o lançamento financeiro: ' + erroFinanca.message);
    carregarTudo();
  }

  async function criarLancamento(form) {
    if (form.parcelado && form.parcelas && form.parcelas.length > 1) {
      const grupoId = crypto.randomUUID();
      const linhas = form.parcelas.map((p, idx) => ({
        cliente: form.cliente,
        projeto: form.projeto,
        valor: Number(p.valor),
        valor_bruto: Number(p.valor),
        com_nf: false,
        data_trabalho: form.dataTrabalho,
        data_pagamento: p.data,
        pago: false,
        parcela_numero: idx + 1,
        parcela_total: form.parcelas.length,
        grupo_parcelamento: grupoId,
      }));
      const { error } = await supabase.from('financas').insert(linhas);
      if (error) { alert('Erro ao salvar as parcelas: ' + error.message); return; }
      carregarTudo();
      return;
    }
    const valor = Number(form.valor);
    const { error } = await supabase.from('financas').insert({
      cliente: form.cliente,
      projeto: form.projeto,
      valor,
      valor_bruto: valor,
      com_nf: false,
      data_trabalho: form.dataTrabalho,
      data_pagamento: form.dataPagamento,
      pago: !!form.pago,
      parcela_numero: 1,
      parcela_total: 1,
    });
    if (error) { alert('Erro ao salvar lançamento: ' + error.message); return; }
    carregarTudo();
  }

  async function atualizarLancamento(grupo, form) {
    const primeiro = grupo.itens[0];
    const filtroColuna = primeiro.grupoParcelamento ? 'grupo_parcelamento' : 'id';
    const filtroValor = primeiro.grupoParcelamento || primeiro.id;
    const origemDemandaId = primeiro.origemDemandaId || null;

    const pagoPorParcela = {};
    grupo.itens.forEach((f) => { pagoPorParcela[f.parcelaNumero || 1] = f.pago; });

    const { error: erroExcluir } = await supabase.from('financas').delete().eq(filtroColuna, filtroValor);
    if (erroExcluir) { alert('Erro ao atualizar lançamento: ' + erroExcluir.message); return; }

    if (form.parcelado && form.parcelas.length > 1) {
      const grupoId = crypto.randomUUID();
      const linhas = form.parcelas.map((p, idx) => ({
        cliente: form.cliente,
        projeto: form.projeto,
        valor: Number(p.valor),
        valor_bruto: Number(p.valor),
        com_nf: false,
        data_trabalho: form.dataTrabalho,
        data_pagamento: p.data,
        pago: pagoPorParcela[idx + 1] || false,
        origem_demanda_id: origemDemandaId,
        parcela_numero: idx + 1,
        parcela_total: form.parcelas.length,
        grupo_parcelamento: grupoId,
      }));
      const { error } = await supabase.from('financas').insert(linhas);
      if (error) alert('Erro ao salvar as parcelas: ' + error.message);
    } else {
      const valor = Number(form.valor);
      const { error } = await supabase.from('financas').insert({
        cliente: form.cliente,
        projeto: form.projeto,
        valor,
        valor_bruto: valor,
        com_nf: false,
        data_trabalho: form.dataTrabalho,
        data_pagamento: form.dataPagamento,
        pago: pagoPorParcela[1] || !!form.pago,
        origem_demanda_id: origemDemandaId,
        parcela_numero: 1,
        parcela_total: 1,
      });
      if (error) alert('Erro ao salvar lançamento: ' + error.message);
    }
    carregarTudo();
  }

  async function atualizarStatusPagamento(f, novoPago) {
    const { error } = await supabase.from('financas').update({ pago: novoPago }).eq('id', f.id);
    if (error) { alert('Erro ao atualizar status: ' + error.message); return; }

    if (f.origemDemandaId) {
      const { data: relacionadas } = await supabase
        .from('financas')
        .select('pago')
        .eq('origem_demanda_id', f.origemDemandaId);
      const todasPagas = (relacionadas || []).length > 0 && relacionadas.every((r) => r.pago);
      if (todasPagas) {
        await supabase.from('demandas').update({ status: 'concluido' }).eq('id', f.origemDemandaId);
      } else {
        const { data: demandaAtual } = await supabase.from('demandas').select('status').eq('id', f.origemDemandaId).single();
        if (demandaAtual?.status === 'concluido') {
          await supabase.from('demandas').update({ status: 'aguardando_pagamento' }).eq('id', f.origemDemandaId);
        }
      }
    }
    carregarTudo();
  }

  async function excluirLancamento(f) {
    const query = f.grupoParcelamento
      ? supabase.from('financas').delete().eq('grupo_parcelamento', f.grupoParcelamento)
      : supabase.from('financas').delete().eq('id', f.id);
    const { error } = await query;
    if (error) { alert('Erro ao excluir: ' + error.message); return; }
    carregarTudo();
  }

  async function criarGasto(form) {
    const { error } = await supabase.from('gastos').insert({
      projeto: form.projeto,
      cliente: form.cliente,
      descricao: form.descricao,
      valor: Number(form.valor),
      data: form.data,
    });
    if (error) { alert('Erro ao salvar gasto: ' + error.message); return; }
    carregarTudo();
  }

  async function excluirGasto(item) {
    const { error } = await supabase.from('gastos').delete().eq('id', item.id);
    if (error) { alert('Erro ao excluir: ' + error.message); return; }
    carregarTudo();
  }

  if (!supabaseConfigurado) {
    return (
      <div style={{ background: '#FAF8F5', minHeight: '100vh', color: '#2B2724', fontFamily: "'Inter', sans-serif" }} className="flex items-center justify-center p-6 text-center">
        <div style={{ maxWidth: 420 }}>
          <p className="mono text-xs tracking-widest mb-2" style={{ color: '#B4483D' }}>CONFIGURAÇÃO PENDENTE</p>
          <p className="text-sm" style={{ color: '#8C8478' }}>
            Crie um arquivo <code>.env</code> na raiz do projeto com <code>VITE_SUPABASE_URL</code> e{' '}
            <code>VITE_SUPABASE_ANON_KEY</code>. Veja o passo a passo no README.
          </p>
        </div>
      </div>
    );
  }

  if (!authCarregado) {
    return <div style={{ background: '#FAF8F5', minHeight: '100vh' }} />;
  }

  if (!session) {
    return <TelaLogin />;
  }

  if (!carregado) {
    return (
      <div style={{ background: '#FAF8F5', minHeight: '100vh', color: '#8C8478', fontFamily: "'Inter', sans-serif" }} className="flex items-center justify-center">
        <p className="mono text-xs tracking-widest">CARREGANDO DADOS...</p>
      </div>
    );
  }

  return (
    <div style={{ background: '#FAF8F5', minHeight: '100%', color: '#2B2724', fontFamily: "'Inter', sans-serif" }} className="p-5 md:p-8 app-shell">
      {erroConexao && (
        <div className="mono text-xs rounded p-2 mb-4" style={{ background: '#B4483D1F', border: '1px solid #B4483D55', color: '#B4483D' }}>
          Não foi possível sincronizar com o banco de dados agora. Verifique sua internet — tentaremos de novo automaticamente.
        </div>
      )}
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Inter:wght@400;500;600;700&display=swap');
        .mono { font-family: 'Manrope', monospace; }
        .card { background: #FFFFFF; border: 1px solid #E8E3DC; transition: border-color .15s ease, transform .15s ease; }
        .card:hover.hoverable { border-color: #3A3A3A; transform: translateY(-1px); }
        .letterbox { height: 4px; background: #E8E3DC; }
        .focusable:focus-visible { outline: 2px solid #C39B99; outline-offset: 2px; }
        select, input, textarea { background: #FFFFFF; border: 1px solid #E8E3DC; color: #2B2724; font-family: 'Inter', sans-serif; }
        select:focus, input:focus, textarea:focus { outline: 2px solid #C39B99; outline-offset: 1px; }
        .day-cell { border: 1px solid #EFEAE3; transition: border-color .15s ease, background .15s ease; }
        .day-cell:hover { border-color: #C39B99; cursor: pointer; }
        .badge-btn { cursor: pointer; border: none; }
        .subtab { font-family: 'Manrope', monospace; }
        @media print {
          body, #root { background: #ffffff !important; }
          .app-shell { background: #ffffff !important; padding: 0 !important; }
          @page { margin: 16mm; }
        }
      `}</style>

      {/* Header */}
      <div className="flex flex-col gap-4 mb-6 print:hidden">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 sm:gap-3 min-w-0">
            <img src={LOGO_SRC} alt="Pâmela Mees Penteados" className="w-11 h-11 sm:w-16 sm:h-16 rounded-full flex-shrink-0" style={{ objectFit: 'cover' }} />
            <div className="min-w-0">
              <div className="hidden sm:flex items-center gap-2 mb-1">
                <span className="mono text-xs tracking-widest" style={{ color: '#8C8478' }}>PAINEL DE ATENDIMENTOS</span>
              </div>
              <h1 className="mono text-lg sm:text-2xl md:text-3xl font-semibold tracking-tight truncate">Pâmela Mees Penteados</h1>
            </div>
          </div>
          <div className="flex items-center gap-2 flex-shrink-0">
            <button
              onClick={baixarBackupCompleto}
              className="focusable mono text-xs font-semibold px-2.5 py-2 rounded flex items-center gap-1.5"
              style={{ background: 'transparent', color: '#8C8478', border: '1px solid #E8E3DC' }}
              title="Baixar backup completo de todos os dados"
            >
              <FileDown size={14} /> <span className="hidden sm:inline">Backup</span>
            </button>
            <button
              onClick={handleLogout}
              className="focusable mono text-xs font-semibold px-2.5 py-2 rounded"
              style={{ background: 'transparent', color: '#8C8478', border: '1px solid #E8E3DC' }}
              title="Sair"
            >
              Sair
            </button>
          </div>
        </div>

        <div className="flex items-center justify-between gap-2 flex-wrap">
          <nav className="flex gap-1 p-1 rounded flex-wrap" style={{ background: '#FFFFFF', border: '1px solid #E8E3DC' }}>
            {[
              { key: 'demandas', label: 'Atendimentos', icon: LayoutGrid },
              { key: 'agenda', label: 'Agenda', icon: CalendarIcon },
              { key: 'financeiro', label: 'Financeiro', icon: Wallet },
            ].map(({ key, label, icon: Icon }) => (
              <button
                key={key}
                onClick={() => setAba(key)}
                className="focusable mono flex items-center gap-2 px-3 sm:px-4 py-2 rounded text-xs sm:text-sm font-semibold"
                style={{ background: aba === key ? '#C39B99' : 'transparent', color: aba === key ? '#2B2724' : '#8C8478' }}
              >
                <Icon size={14} /> {label}
              </button>
            ))}
          </nav>
          <span className="mono text-[11px] truncate" style={{ color: '#8C8478' }}>{session.user.email}</span>
        </div>
      </div>

      {aba === 'demandas' && <TelaDemandas demandas={demandas} financas={financas} onCriar={criarDemanda} onAtualizar={atualizarDemanda} onExcluir={excluirDemanda} />}
      {aba === 'agenda' && <TelaAgenda demandas={demandas} financas={financas} />}
      {aba === 'financeiro' && <TelaFinanceiro financas={financas} gastos={gastos} demandas={demandas} onCriarLancamento={criarLancamento} onAtualizarLancamento={atualizarLancamento} onAtualizarStatus={atualizarStatusPagamento} onExcluirLancamento={excluirLancamento} onCriarGasto={criarGasto} onExcluirGasto={excluirGasto} />}
    </div>
  );
}

/* ---------- Seletor de múltiplos dias (usado na gravação) ---------- */
function SeletorDiasMultiplos({ selecionados, onChange }) {
  const [mesAtual, setMesAtual] = useState(new Date());
  const dias = useMemo(() => gerarDias(mesAtual.getFullYear(), mesAtual.getMonth()), [mesAtual]);

  function alternar(chave) {
    if (selecionados.includes(chave)) onChange(selecionados.filter((d) => d !== chave));
    else onChange([...selecionados, chave].sort());
  }

  return (
    <div className="rounded p-2" style={{ border: '1px solid #E8E3DC' }}>
      <div className="flex items-center justify-between mb-2">
        <button type="button" onClick={() => setMesAtual(new Date(mesAtual.getFullYear(), mesAtual.getMonth() - 1, 1))} className="focusable p-1" aria-label="Mês anterior">
          <ChevronLeft size={14} color="#8C8478" />
        </button>
        <span className="mono text-[11px] tracking-widest">{MESES[mesAtual.getMonth()].toUpperCase()} {mesAtual.getFullYear()}</span>
        <button type="button" onClick={() => setMesAtual(new Date(mesAtual.getFullYear(), mesAtual.getMonth() + 1, 1))} className="focusable p-1" aria-label="Próximo mês">
          <ChevronRight size={14} color="#8C8478" />
        </button>
      </div>
      <div className="grid grid-cols-7 gap-1 mb-1">
        {DIAS_SEMANA.map((d, i) => <div key={i} className="mono text-[9px] text-center" style={{ color: '#8C8478' }}>{d}</div>)}
      </div>
      <div className="grid grid-cols-7 gap-1">
        {dias.map((d, i) => {
          if (!d) return <div key={i} />;
          const chave = chaveData(d);
          const ativo = selecionados.includes(chave);
          return (
            <button
              type="button"
              key={i}
              onClick={() => alternar(chave)}
              className="focusable mono text-[10px] rounded"
              style={{ padding: '5px 0', background: ativo ? '#C39B99' : 'transparent', color: '#2B2724', border: '1px solid #E8E3DC' }}
            >
              {d.getDate()}
            </button>
          );
        })}
      </div>
      <div className="mono text-[10px] mt-2" style={{ color: '#8C8478' }}>
        {selecionados.length === 0 ? 'Nenhum dia selecionado' : `${selecionados.length} dia${selecionados.length === 1 ? '' : 's'} selecionado${selecionados.length === 1 ? '' : 's'}`}
      </div>
    </div>
  );
}

/* ---------- Tela: Demandas ---------- */
function TelaDemandas({ demandas, financas, onCriar, onAtualizar, onExcluir }) {
  const [filtroCliente, setFiltroCliente] = useState('Todos');
  const [filtroStatus, setFiltroStatus] = useState('ativos');
  const [formAberto, setFormAberto] = useState(false);
  const [editando, setEditando] = useState(null);
  const [expandido, setExpandido] = useState(null);
  const [form, setForm] = useState(emptyDemanda);

  const clientes = useMemo(() => ['Todos', ...Array.from(new Set(demandas.map((d) => d.cliente)))], [demandas]);

  const contagem = useMemo(() => {
    const c = { pre_reserva: 0, confirmado: 0, aguardando_pagamento: 0, atrasado: 0, concluido: 0 };
    demandas.forEach((d) => { c[statusExibicaoChave(d, financas)] += 1; });
    return c;
  }, [demandas, financas]);

  const lista = useMemo(() => {
    return demandas
      .filter((d) => filtroCliente === 'Todos' || d.cliente === filtroCliente)
      .filter((d) => {
        if (filtroStatus === 'Todos') return true;
        if (filtroStatus === 'ativos') return d.status !== 'concluido';
        return statusExibicaoChave(d, financas) === filtroStatus;
      })
      .sort((a, b) => {
        const aConcluida = a.status === 'concluido' ? 1 : 0;
        const bConcluida = b.status === 'concluido' ? 1 : 0;
        if (aConcluida !== bConcluida) return aConcluida - bConcluida;
        return diasRestantes(a.prazo) - diasRestantes(b.prazo);
      });
  }, [demandas, financas, filtroCliente, filtroStatus]);

  function abrirNova() {
    setEditando(null);
    setForm(emptyDemanda);
    setFormAberto(true);
  }

  function abrirEdicao(demanda) {
    const financasVinculadas = financas.filter((f) => f.origemDemandaId === demanda.id).sort((a, b) => (a.parcelaNumero || 1) - (b.parcelaNumero || 1));
    const parcelado = financasVinculadas.length > 1;
    setForm({
      cliente: demanda.cliente,
      projeto: demanda.projeto,
      etapa: demanda.etapa,
      prazo: demanda.prazo,
      horario: demanda.horario || '',
      status: demanda.status,
      dataGravacao: demanda.dataGravacao || null,
      datasGravacao: demanda.datasGravacao || [],
      descricao: demanda.descricao || '',
      endereco: demanda.endereco || '',
      noEstudio: demanda.noEstudio || false,
      quantidadePessoas: demanda.quantidadePessoas || 1,
      valor: demanda.valor,
      comNF: demanda.comNF,
      dataPagamento: parcelado ? '' : (financasVinculadas[0]?.dataPagamento || ''),
      parcelado,
      parcelas: parcelado ? financasVinculadas.map((f) => ({ valor: f.valorBruto ?? f.valor, data: f.dataPagamento })) : [],
    });
    setEditando(demanda.id);
    setFormAberto(true);
  }

  function fecharForm() {
    setFormAberto(false);
    setEditando(null);
    setForm(emptyDemanda);
  }

  async function salvar(e) {
    e.preventDefault();
    if (!form.cliente || !form.projeto || !form.prazo || !form.valor) return;
    if (editando) await onAtualizar(editando, form);
    else await onCriar(form);
    fecharForm();
  }

  async function excluir(demanda) {
    const confirmar = window.confirm(`Excluir o atendimento "${demanda.projeto}" (${demanda.cliente})?\n\nIsso também remove o lançamento correspondente no Financeiro. Essa ação não pode ser desfeita.`);
    if (!confirmar) return;
    await onExcluir(demanda);
  }

  const maxContagem = Math.max(1, ...Object.values(contagem));

  return (
    <div>
      <div className="flex justify-end mb-4">
        <button onClick={abrirNova} className="focusable flex items-center gap-2 px-4 py-2 rounded mono text-sm font-semibold" style={{ background: '#C39B99', color: '#2B2724' }}>
          <Plus size={16} /> Novo atendimento
        </button>
      </div>

      <div className="card rounded-lg p-4 md:p-5 mb-6">
        <div className="mono text-xs tracking-widest mb-3" style={{ color: '#8C8478' }}>DISTRIBUIÇÃO POR STATUS</div>
        <div className="flex items-end gap-6 h-20">
          {Object.entries(STATUS).map(([key, s]) => (
            <div key={key} className="flex flex-col items-center gap-2 flex-1">
              <div className="w-full flex items-end justify-center" style={{ height: 56 }}>
                <div style={{ width: 28, height: `${Math.max(6, (contagem[key] / maxContagem) * 56)}px`, background: s.color, borderRadius: 2 }} />
              </div>
              <div className="mono text-[11px] text-center" style={{ color: '#8C8478' }}>{contagem[key]} · {s.label}</div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3 mb-6">
        <FilterIcon size={14} color="#8C8478" />
        <select value={filtroCliente} onChange={(e) => setFiltroCliente(e.target.value)} className="focusable rounded px-3 py-1.5 text-sm">
          {clientes.map((c) => <option key={c}>{c}</option>)}
        </select>
        <select value={filtroStatus} onChange={(e) => setFiltroStatus(e.target.value)} className="focusable rounded px-3 py-1.5 text-sm">
          <option value="ativos">Em aberto (não concluídos)</option>
          <option value="Todos">Todos os status</option>
          {Object.entries(STATUS).map(([key, s]) => <option key={key} value={key}>{s.label}</option>)}
        </select>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {lista.map((d) => {
          const dias = diasRestantes(d.prazo);
          const s = STATUS[statusExibicaoChave(d, financas)];
          const aberto = expandido === d.id;
          const financaVinculada = financas.find((f) => f.origemDemandaId === d.id);
          return (
            <div key={d.id} className="card hoverable rounded-lg overflow-hidden">
              <div className="letterbox" />
              <div className="p-4" style={{ borderLeft: `3px solid ${s.color}` }}>
                <div className="flex items-center justify-between mb-2">
                  <span className="text-xs" style={{ color: '#8C8478' }}>{d.cliente}</span>
                  <span className="mono text-xs font-semibold" style={{ color: s.color }}>{prazoLabel(dias)}</span>
                </div>
                <h3 className="font-semibold text-base mb-3">{d.projeto}</h3>
                <div className="flex gap-1 mb-2">
                  {ETAPAS.map((et) => (
                    <div key={et} style={{ flex: 1, height: 4, borderRadius: 2, background: et === d.etapa ? s.color : '#E8E3DC' }} title={et} />
                  ))}
                </div>

                <button
                  onClick={() => setExpandido(aberto ? null : d.id)}
                  className="focusable flex items-center justify-between w-full mt-1"
                  aria-expanded={aberto}
                >
                  <span className="mono text-[11px] tracking-wide" style={{ color: '#8C8478' }}>{d.etapa.toUpperCase()}</span>
                  <ChevronDown size={14} color="#8C8478" style={{ transform: aberto ? 'rotate(180deg)' : 'none', transition: 'transform .15s ease' }} />
                </button>

                {aberto && (
                  <div className="mt-3 pt-3 flex flex-col gap-2" style={{ borderTop: '1px solid #E8E3DC' }}>
                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <div className="mono text-[10px] tracking-widest" style={{ color: '#8C8478' }}>VALOR</div>
                        <div className="mono text-sm font-semibold">{moeda(d.valor)}</div>
                        {d.comNF && <div className="mono text-[10px]" style={{ color: '#8C8478' }}>líq. {moeda(valorLiquidoTrabalho(d.valor, true))}</div>}
                      </div>
                      <div>
                        <div className="mono text-[10px] tracking-widest" style={{ color: '#8C8478' }}>NOTA FISCAL</div>
                        <div className="mono text-sm font-semibold">{d.comNF ? 'Com NF' : 'Sem NF'}</div>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <div className="mono text-[10px] tracking-widest" style={{ color: '#8C8478' }}>STATUS</div>
                        <div className="text-sm" style={{ color: s.color }}>{s.label}</div>
                      </div>
                      <div>
                        <div className="mono text-[10px] tracking-widest" style={{ color: '#8C8478' }}>DATA DE PAGAMENTO</div>
                        <div className="text-sm">{financaVinculada ? new Date(financaVinculada.dataPagamento + 'T00:00:00').toLocaleDateString('pt-BR') : '—'}</div>
                      </div>
                    </div>
                    {d.etapa === 'Atendimento' && d.datasGravacao && d.datasGravacao.length > 0 && (
                      <div>
                        <div className="mono text-[10px] tracking-widest mb-1" style={{ color: '#8C8478' }}>DIAS DE ATENDIMENTO</div>
                        <div className="flex flex-wrap gap-1">
                          {d.datasGravacao.map((data) => (
                            <span key={data} className="mono text-[10px] px-1.5 py-0.5 rounded" style={{ background: '#C39B991A', border: '1px solid #C39B9955', color: '#C39B99' }}>
                              {new Date(data + 'T00:00:00').toLocaleDateString('pt-BR')}
                            </span>
                          ))}
                        </div>
                      </div>
                    )}
                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <div className="mono text-[10px] tracking-widest" style={{ color: '#8C8478' }}>PESSOAS ATENDIDAS</div>
                        <div className="text-sm flex items-center gap-1"><Users size={12} /> {d.quantidadePessoas || 1}</div>
                      </div>
                      <div>
                        <div className="mono text-[10px] tracking-widest" style={{ color: '#8C8478' }}>LOCAL</div>
                        {d.noEstudio ? (
                          <div className="text-sm">No próprio estúdio</div>
                        ) : d.endereco ? (
                          <a
                            href={`https://waze.com/ul?q=${encodeURIComponent(d.endereco)}&navigate=yes`}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="focusable flex items-center gap-1 text-sm"
                            style={{ color: '#C39B99' }}
                          >
                            <Navigation size={12} /> {d.endereco}
                          </a>
                        ) : (
                          <div className="text-sm">—</div>
                        )}
                      </div>
                    </div>
                    {d.descricao && (
                      <div>
                        <div className="mono text-[10px] tracking-widest mb-1" style={{ color: '#8C8478' }}>DESCRIÇÃO</div>
                        <p className="text-sm" style={{ color: '#2B2724' }}>{d.descricao}</p>
                      </div>
                    )}
                  </div>
                )}

                <div className="flex justify-end gap-3 mt-3">
                  <button
                    onClick={() => abrirEdicao(d)}
                    className="focusable flex items-center gap-1 mono text-[11px]"
                    style={{ color: '#8C8478' }}
                    title="Editar atendimento"
                  >
                    <Pencil size={12} /> Editar
                  </button>
                  <button
                    onClick={() => excluir(d)}
                    className="focusable flex items-center gap-1 mono text-[11px]"
                    style={{ color: '#8C8478' }}
                    title="Excluir atendimento"
                  >
                    <Trash2 size={12} /> Excluir
                  </button>
                </div>
              </div>
              <div className="letterbox" />
            </div>
          );
        })}
        {lista.length === 0 && <div className="col-span-full text-center py-12 mono text-sm" style={{ color: '#8C8478' }}>Nenhum atendimento com esse filtro.</div>}
      </div>

      {formAberto && (
        <div className="fixed inset-0 flex items-start sm:items-center justify-center p-4 overflow-y-auto py-8" style={{ background: 'rgba(0,0,0,0.6)' }}>
          <form onSubmit={salvar} className="card rounded-lg p-6 w-full max-w-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="mono text-sm tracking-widest" style={{ color: '#8C8478' }}>{editando ? 'EDITAR ATENDIMENTO' : 'NOVO ATENDIMENTO'}</h2>
              <button type="button" onClick={fecharForm} className="focusable" aria-label="Fechar"><X size={18} color="#8C8478" /></button>
            </div>
            <div className="flex flex-col gap-3">
              <input required placeholder="Cliente" value={form.cliente} onChange={(e) => setForm({ ...form, cliente: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <select required value={form.projeto} onChange={(e) => setForm({ ...form, projeto: e.target.value })} className="focusable rounded px-3 py-2 text-sm">
                <option value="">Selecione o serviço</option>
                {SERVICOS.map((s) => <option key={s} value={s}>{s}</option>)}
              </select>
              <select
                value={form.etapa}
                onChange={(e) => {
                  const novaEtapa = e.target.value;
                  const novoStatus = novaEtapa === 'Finalizado' && form.status !== 'concluido' ? 'aguardando_pagamento' : form.status;
                  setForm({ ...form, etapa: novaEtapa, status: novoStatus });
                }}
                className="focusable rounded px-3 py-2 text-sm"
              >
                {ETAPAS.map((et) => <option key={et}>{et}</option>)}
              </select>
              {form.etapa === 'Atendimento' && (
                <div className="flex flex-col gap-1">
                  <span className="mono text-[11px]" style={{ color: '#8C8478' }}>DIAS DE ATENDIMENTO</span>
                  <SeletorDiasMultiplos
                    selecionados={form.datasGravacao}
                    onChange={(novos) => setForm({ ...form, datasGravacao: novos, prazo: novos.length > 0 ? novos[novos.length - 1] : form.prazo })}
                  />
                </div>
              )}
              {form.etapa !== 'Atendimento' && (
                <div className="flex flex-col gap-1">
                  <span className="mono text-[11px]" style={{ color: '#8C8478' }}>DATA</span>
                  <input required type="date" value={form.prazo} onChange={(e) => setForm({ ...form, prazo: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                </div>
              )}
              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#8C8478' }}>HORÁRIO</span>
                <input type="time" value={form.horario} onChange={(e) => setForm({ ...form, horario: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              </div>
              <select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className="focusable rounded px-3 py-2 text-sm">
                {form.status === 'concluido' && <option value="concluido" disabled>{STATUS.concluido.label} (automático)</option>}
                {form.status === 'atrasado' && <option value="atrasado" disabled>{STATUS.atrasado.label} (automático)</option>}
                {Object.entries(STATUS_SELECIONAVEIS).map(([key, s]) => <option key={key} value={key}>{s.label}</option>)}
              </select>

              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#8C8478' }}>DESCRIÇÃO (opcional)</span>
                <textarea
                  placeholder="Detalhes do trabalho, referências, observações..."
                  value={form.descricao}
                  onChange={(e) => setForm({ ...form, descricao: e.target.value })}
                  rows={3}
                  className="focusable rounded px-3 py-2 text-sm resize-none"
                />
              </div>

              <div className="flex flex-col gap-1">
                <label className="flex items-center gap-2 text-sm mono" style={{ color: '#8C8478' }}>
                  <input
                    type="checkbox"
                    checked={form.quantidadePessoas > 1}
                    onChange={(e) => setForm({ ...form, quantidadePessoas: e.target.checked ? 2 : 1 })}
                    style={{ accentColor: '#C39B99' }}
                  />
                  Atende mais de uma pessoa nesse horário?
                </label>
                {form.quantidadePessoas > 1 && (
                  <div className="flex flex-col gap-1 mt-1">
                    <span className="mono text-[11px]" style={{ color: '#8C8478' }}>QUANTAS PESSOAS AO TODO (ex: noiva + 3 penteados = 4)</span>
                    <input
                      type="number"
                      min={2}
                      value={form.quantidadePessoas}
                      onChange={(e) => setForm({ ...form, quantidadePessoas: e.target.value })}
                      className="focusable rounded px-3 py-2 text-sm"
                    />
                  </div>
                )}
              </div>

              <label className="flex items-center gap-2 text-sm mono" style={{ color: '#8C8478' }}>
                <input
                  type="checkbox"
                  checked={form.noEstudio}
                  onChange={(e) => setForm({ ...form, noEstudio: e.target.checked, endereco: e.target.checked ? '' : form.endereco })}
                  style={{ accentColor: '#C39B99' }}
                />
                Atendimento no próprio estúdio
              </label>

              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#8C8478' }}>ENDEREÇO {form.noEstudio ? '(não se aplica — atendimento no estúdio)' : '(opcional)'}</span>
                <div className="flex gap-2">
                  <input
                    type="text"
                    placeholder="Rua, número, bairro, cidade..."
                    value={form.endereco}
                    disabled={form.noEstudio}
                    onChange={(e) => setForm({ ...form, endereco: e.target.value })}
                    className="focusable rounded px-3 py-2 text-sm flex-1"
                    style={form.noEstudio ? { opacity: 0.5 } : {}}
                  />
                  {!form.noEstudio && form.endereco && (
                    <a
                      href={`https://waze.com/ul?q=${encodeURIComponent(form.endereco)}&navigate=yes`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="focusable flex items-center justify-center rounded px-3 flex-shrink-0"
                      style={{ background: '#F1EBE4', border: '1px solid #E8E3DC', color: '#2B2724' }}
                      title="Abrir no Waze"
                    >
                      <Navigation size={16} />
                    </a>
                  )}
                </div>
              </div>

              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#8C8478' }}>VALOR DO SERVIÇO (R$)</span>
                <input required type="number" placeholder="0,00" value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              </div>

              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#8C8478' }}>NOTA FISCAL</span>
                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={() => setForm({ ...form, comNF: true })}
                    className="focusable flex-1 mono text-xs font-semibold py-2 rounded"
                    style={{ background: form.comNF ? '#4C7A5E' : 'transparent', color: form.comNF ? '#FFFFFF' : '#8C8478', border: '1px solid #E8E3DC' }}
                  >
                    COM NF (–6%)
                  </button>
                  <button
                    type="button"
                    onClick={() => setForm({ ...form, comNF: false })}
                    className="focusable flex-1 mono text-xs font-semibold py-2 rounded"
                    style={{ background: !form.comNF ? '#A89B8C' : 'transparent', color: !form.comNF ? '#FFFFFF' : '#8C8478', border: '1px solid #E8E3DC' }}
                  >
                    SEM NF
                  </button>
                </div>
                {form.valor > 0 && (
                  <span className="mono text-[11px] mt-1" style={{ color: '#8C8478' }}>
                    Valor a receber: {moeda(valorLiquidoTrabalho(Number(form.valor), form.comNF))}
                  </span>
                )}
              </div>

              <CamposParcelamento form={form} setForm={setForm} />

              {!form.parcelado && (
                <div className="flex flex-col gap-1">
                  <span className="mono text-[11px]" style={{ color: '#8C8478' }}>DATA DE PAGAMENTO (opcional)</span>
                  <input type="date" value={form.dataPagamento} onChange={(e) => setForm({ ...form, dataPagamento: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                </div>
              )}

              <button type="submit" className="focusable mono text-sm font-semibold rounded py-2 mt-1" style={{ background: '#C39B99', color: '#2B2724' }}>{editando ? 'Salvar alterações' : 'Adicionar'}</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

/* ---------- Tela: Agenda ---------- */
function expandirIntervalo(inicio, fim) {
  const chaves = [];
  let atual = new Date(inicio + 'T00:00:00');
  const final = new Date((fim || inicio) + 'T00:00:00');
  while (atual <= final) {
    chaves.push(chaveData(atual));
    atual = new Date(atual.getFullYear(), atual.getMonth(), atual.getDate() + 1);
  }
  return chaves;
}
const emptyEvento = { titulo: '', cliente: '', tipo: 'gravacao', descricao: '', diaTodo: true, dataInicio: '', dataFim: '', horaInicio: '', horaFim: '', datasSelecionadas: [] };

function TelaAgenda({ demandas, financas }) {
  const [mesAtual, setMesAtual] = useState(() => { const hoje = new Date(); return new Date(hoje.getFullYear(), hoje.getMonth(), 1); });
  const [diaSelecionado, setDiaSelecionado] = useState(null);
  const [eventosManuais, setEventosManuais] = useState([]);
  const [formAberto, setFormAberto] = useState(false);
  const [form, setForm] = useState(emptyEvento);
  const [cores, setCores] = useState(() =>
    Object.fromEntries(Object.entries(TIPO_EVENTO).map(([key, t]) => [key, t.color]))
  );

  const dias = useMemo(() => gerarDias(mesAtual.getFullYear(), mesAtual.getMonth()), [mesAtual]);

  const eventosPorDia = useMemo(() => {
    const map = {};
    const add = (data, ev) => { if (!data) return; if (!map[data]) map[data] = []; map[data].push(ev); };
    demandas.forEach((d) => {
      const temHorario = Boolean(d.horario);
      if (d.etapa === 'Consulta') add(d.prazo, { id: `b-${d.id}`, titulo: `Consulta — ${d.projeto}`, tipo: 'briefing', cliente: d.cliente, diaTodo: !temHorario, horaInicio: d.horario, descricao: d.descricao, endereco: d.endereco, noEstudio: d.noEstudio, quantidadePessoas: d.quantidadePessoas });
      if (d.etapa === 'Atendimento') {
        const diasGravacao = (d.datasGravacao && d.datasGravacao.length > 0) ? d.datasGravacao : (d.dataGravacao ? [d.dataGravacao] : [d.prazo]);
        diasGravacao.forEach((data, idx) => add(data, { id: `g-${d.id}-${idx}`, titulo: `Atendimento — ${d.projeto}`, tipo: 'gravacao', cliente: d.cliente, diaTodo: !temHorario, horaInicio: d.horario, descricao: d.descricao, endereco: d.endereco, noEstudio: d.noEstudio, quantidadePessoas: d.quantidadePessoas }));
      }
      if (d.etapa === 'Finalizado') add(d.prazo, { id: `e-${d.id}`, titulo: `Finalizado — ${d.projeto}`, tipo: 'entrega', cliente: d.cliente, diaTodo: !temHorario, horaInicio: d.horario, descricao: d.descricao, endereco: d.endereco, noEstudio: d.noEstudio, quantidadePessoas: d.quantidadePessoas });
    });
    financas.forEach((f) => add(f.dataPagamento, { id: `p-${f.id}`, titulo: `Pagamento — ${f.projeto}`, tipo: 'pagamento', cliente: f.cliente, diaTodo: true }));
    eventosManuais.forEach((ev) => {
      expandirIntervalo(ev.dataInicio, ev.dataFim).forEach((chave) => add(chave, ev));
    });
    return map;
  }, [demandas, financas, eventosManuais]);

  const eventosDoDia = diaSelecionado ? ordenarEventosDia(eventosPorDia[chaveData(diaSelecionado)] || []) : [];

  const diasComEventoNoMes = useMemo(() => {
    return dias
      .filter((d) => d && (eventosPorDia[chaveData(d)] || []).length > 0)
      .map((d) => ({ data: d, eventos: ordenarEventosDia(eventosPorDia[chaveData(d)]) }));
  }, [dias, eventosPorDia]);

  function exportarPDF() {
    window.print();
  }

  function trocarMes(delta) {
    setMesAtual(new Date(mesAtual.getFullYear(), mesAtual.getMonth() + delta, 1));
    setDiaSelecionado(null);
  }

  function adicionarTrabalho(e) {
    e.preventDefault();
    if (!form.titulo || !form.cliente) return;

    if (form.tipo === 'gravacao') {
      if (!form.datasSelecionadas || form.datasSelecionadas.length === 0) return;
      const novos = form.datasSelecionadas.map((data, idx) => ({
        id: `m-${Date.now()}-${idx}`,
        titulo: form.titulo,
        cliente: form.cliente,
        tipo: form.tipo,
        descricao: form.descricao,
        diaTodo: true,
        dataInicio: data,
        dataFim: data,
      }));
      setEventosManuais((prev) => [...prev, ...novos]);
      const primeira = new Date(form.datasSelecionadas[0] + 'T00:00:00');
      setDiaSelecionado(primeira);
      setMesAtual(new Date(primeira.getFullYear(), primeira.getMonth(), 1));
    } else {
      if (!form.dataInicio) return;
      const novo = { ...form, dataFim: form.dataFim || form.dataInicio, id: `m-${Date.now()}` };
      setEventosManuais((prev) => [...prev, novo]);
      const inicio = new Date(novo.dataInicio + 'T00:00:00');
      setDiaSelecionado(inicio);
      setMesAtual(new Date(inicio.getFullYear(), inicio.getMonth(), 1));
    }

    setForm(emptyEvento);
    setFormAberto(false);
  }

  function excluirEvento(ev) {
    const confirmar = window.confirm(`Excluir o evento "${ev.titulo}"? Essa ação não pode ser desfeita.`);
    if (!confirmar) return;
    setEventosManuais((prev) => prev.filter((e) => e.id !== ev.id));
  }

  return (
    <div>
      <div className="flex justify-end gap-2 mb-4 print:hidden">
        <button onClick={exportarPDF} className="focusable flex items-center gap-2 px-4 py-2 rounded mono text-sm font-semibold" style={{ background: 'transparent', color: '#8C8478', border: '1px solid #E8E3DC' }}>
          <FileDown size={16} /> Exportar mês (PDF)
        </button>
        <button onClick={() => setFormAberto(true)} className="focusable flex items-center gap-2 px-4 py-2 rounded mono text-sm font-semibold" style={{ background: '#C39B99', color: '#2B2724' }}>
          <Plus size={16} /> Novo compromisso
        </button>
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 print:hidden">
        <div className="card rounded-lg p-2 sm:p-4 md:p-5 lg:col-span-2">
          <div className="flex items-center justify-between mb-4">
            <button onClick={() => trocarMes(-1)} className="focusable p-1 rounded" aria-label="Mês anterior"><ChevronLeft size={20} color="#8C8478" /></button>
            <span
              className="mono text-lg md:text-xl font-bold tracking-widest px-4 py-1.5 rounded"
              style={{ background: '#C39B991A', border: '1px solid #C39B9955', color: '#C39B99' }}
            >
              {MESES[mesAtual.getMonth()].toUpperCase()} {mesAtual.getFullYear()}
            </span>
            <button onClick={() => trocarMes(1)} className="focusable p-1 rounded" aria-label="Próximo mês"><ChevronRight size={20} color="#8C8478" /></button>
          </div>
          <div className="grid grid-cols-7 gap-1 mb-1">
            {DIAS_SEMANA.map((d, i) => <div key={i} className="mono text-[11px] text-center py-1" style={{ color: '#8C8478' }}>{d}</div>)}
          </div>
          <div className="grid grid-cols-7 gap-1">
            {dias.map((d, i) => {
              if (!d) return <div key={i} />;
              const chave = chaveData(d);
              const eventos = ordenarEventosDia(eventosPorDia[chave] || []);
              const selecionado = diaSelecionado && chaveData(diaSelecionado) === chave;
              const visiveis = eventos.slice(0, 2);
              const restante = eventos.length - visiveis.length;
              return (
                <div
                  key={i}
                  onClick={() => setDiaSelecionado(d)}
                  className="day-cell rounded p-0.5 sm:p-1 flex flex-col items-stretch min-h-[64px] sm:min-h-[104px]"
                  style={{ background: selecionado ? 'rgba(245,197,24,0.08)' : 'transparent', borderColor: selecionado ? '#C39B99' : '#EFEAE3' }}
                >
                  <span className="mono text-xs sm:text-sm px-0.5" style={{ color: '#8C8478' }}>{d.getDate()}</span>
                  <div className="flex flex-col gap-0.5 mt-0.5 sm:mt-1">
                    {visiveis.map((ev) => {
                      const bg = cores[ev.tipo] || TIPO_EVENTO[ev.tipo].color;
                      return (
                        <div
                          key={ev.id}
                          className="mono truncate"
                          style={{ background: bg, color: corTexto(bg), fontSize: 10, lineHeight: '16px', borderRadius: 3, padding: '0 3px' }}
                          title={ev.diaTodo === false ? `${ev.horaInicio || ''} ${ev.titulo}` : ev.titulo}
                        >
                          {ev.diaTodo === false && ev.horaInicio ? `${ev.horaInicio} ` : ''}{ev.titulo}
                        </div>
                      );
                    })}
                    {restante > 0 && (
                      <div className="mono px-1" style={{ fontSize: 10, color: '#8C8478' }}>+{restante}</div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
          <div className="flex gap-4 mt-4 flex-wrap items-center">
            {Object.entries(TIPO_EVENTO).map(([key, t]) => (
              <label key={key} className="flex items-center gap-1.5 cursor-pointer">
                <input
                  type="color"
                  value={cores[key]}
                  onChange={(e) => setCores({ ...cores, [key]: e.target.value })}
                  className="focusable"
                  style={{ width: 16, height: 16, padding: 0, border: 'none', borderRadius: 4, background: 'transparent', cursor: 'pointer' }}
                  title={`Cor de ${t.label}`}
                />
                <span className="mono text-[11px]" style={{ color: '#8C8478' }}>{t.label}</span>
              </label>
            ))}
          </div>
        </div>

        <div className="card rounded-lg p-4 md:p-5">
          <div className="mono text-xs tracking-widest mb-3" style={{ color: '#8C8478' }}>
            {diaSelecionado ? `${diaSelecionado.getDate()} DE ${MESES[diaSelecionado.getMonth()].toUpperCase()}` : 'SELECIONE UM DIA'}
          </div>
          {diaSelecionado && eventosDoDia.length === 0 && <p className="text-sm" style={{ color: '#8C8478' }}>Nenhum evento nesse dia.</p>}
          <div className="flex flex-col gap-3">
            {eventosDoDia.map((ev) => {
              const cor = cores[ev.tipo] || TIPO_EVENTO[ev.tipo].color;
              const manual = typeof ev.id === 'string' && ev.id.startsWith('m-');
              return (
                <div key={ev.id} className="pl-3 flex items-start justify-between gap-2" style={{ borderLeft: `3px solid ${cor}` }}>
                  <div>
                    <div className="text-sm font-semibold">{ev.titulo}</div>
                    <div className="text-xs" style={{ color: '#8C8478' }}>{ev.cliente}</div>
                    <div className="mono text-[11px] mt-1" style={{ color: cor }}>
                      {ev.diaTodo === false ? (ev.horaFim ? `${ev.horaInicio || '--:--'} – ${ev.horaFim}` : `${ev.horaInicio || '--:--'}`) : 'DIA TODO'}
                    </div>
                    {ev.quantidadePessoas > 1 && (
                      <div className="flex items-center gap-1 mt-1 mono text-[11px]" style={{ color: '#8C8478' }}>
                        <Users size={12} /> {ev.quantidadePessoas} pessoas
                      </div>
                    )}
                    {ev.noEstudio && <div className="mono text-[11px] mt-1" style={{ color: '#8C8478' }}>No próprio estúdio</div>}
                    {!ev.noEstudio && ev.endereco && (
                      <a
                        href={`https://waze.com/ul?q=${encodeURIComponent(ev.endereco)}&navigate=yes`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="focusable flex items-center gap-1 mt-1 text-xs"
                        style={{ color: '#C39B99' }}
                      >
                        <Navigation size={12} /> {ev.endereco}
                      </a>
                    )}
                    {ev.descricao && <p className="text-xs mt-1" style={{ color: '#8C8478' }}>{ev.descricao}</p>}
                  </div>
                  {manual && (
                    <button onClick={() => excluirEvento(ev)} className="focusable flex-shrink-0" title="Excluir evento" style={{ color: '#8C8478' }}>
                      <Trash2 size={13} />
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Relatório para exportação em PDF — invisível na tela, aparece só ao imprimir/exportar */}
      <div className="hidden print:block" style={{ color: '#000', background: '#fff', fontFamily: 'Arial, sans-serif' }}>
        <h1 style={{ fontSize: 20, fontWeight: 700, marginBottom: 4 }}>Pâmela Mees Penteados — Agenda</h1>
        <h2 style={{ fontSize: 14, fontWeight: 600, marginBottom: 16, color: '#555' }}>{MESES[mesAtual.getMonth()]} de {mesAtual.getFullYear()}</h2>
        {diasComEventoNoMes.length === 0 && <p style={{ fontSize: 13 }}>Nenhum evento neste mês.</p>}
        {diasComEventoNoMes.map(({ data, eventos }) => (
          <div key={chaveData(data)} style={{ marginBottom: 14, breakInside: 'avoid' }}>
            <div style={{ fontSize: 13, fontWeight: 700, borderBottom: '1px solid #ccc', paddingBottom: 4, marginBottom: 6 }}>
              {DIAS_SEMANA_EXTENSO[data.getDay()]}, {String(data.getDate()).padStart(2, '0')}/{String(data.getMonth() + 1).padStart(2, '0')}/{data.getFullYear()}
            </div>
            {eventos.map((ev) => (
              <div key={ev.id} style={{ fontSize: 12, marginBottom: 6, paddingLeft: 8 }}>
                <div style={{ fontWeight: 600 }}>[{TIPO_EVENTO[ev.tipo].label}] {ev.titulo}</div>
                <div style={{ color: '#333' }}>
                  Cliente: {ev.cliente}
                  {ev.diaTodo === false && ` · Horário: ${ev.horaInicio || '--:--'} – ${ev.horaFim || '--:--'}`}
                  {ev.diaTodo !== false && ' · Dia todo'}
                </div>
                {ev.descricao && <div style={{ color: '#555' }}>{ev.descricao}</div>}
              </div>
            ))}
          </div>
        ))}
      </div>

      {formAberto && (
        <div className="fixed inset-0 flex items-start sm:items-center justify-center p-4 overflow-y-auto py-8" style={{ background: 'rgba(0,0,0,0.6)' }}>
          <form onSubmit={adicionarTrabalho} className="card rounded-lg p-6 w-full max-w-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="mono text-sm tracking-widest" style={{ color: '#8C8478' }}>NOVO TRABALHO</h2>
              <button type="button" onClick={() => setFormAberto(false)} className="focusable" aria-label="Fechar"><X size={18} color="#8C8478" /></button>
            </div>
            <div className="flex flex-col gap-3">
              <input required placeholder="Título" value={form.titulo} onChange={(e) => setForm({ ...form, titulo: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required placeholder="Cliente" value={form.cliente} onChange={(e) => setForm({ ...form, cliente: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <select value={form.tipo} onChange={(e) => setForm({ ...form, tipo: e.target.value })} className="focusable rounded px-3 py-2 text-sm">
                {Object.entries(TIPO_EVENTO_FORM).map(([key, t]) => <option key={key} value={key}>{t.label}</option>)}
              </select>
              <textarea placeholder="Descrição do trabalho" value={form.descricao} onChange={(e) => setForm({ ...form, descricao: e.target.value })} rows={3} className="focusable rounded px-3 py-2 text-sm resize-none" />

              {form.tipo === 'gravacao' ? (
                <div className="flex flex-col gap-1">
                  <span className="mono text-[11px]" style={{ color: '#8C8478' }}>DIAS DE ATENDIMENTO</span>
                  <SeletorDiasMultiplos
                    selecionados={form.datasSelecionadas}
                    onChange={(novos) => setForm({ ...form, datasSelecionadas: novos })}
                  />
                </div>
              ) : (
                <>
                  <label className="flex items-center gap-2 text-sm mono" style={{ color: '#8C8478' }}>
                    <input type="checkbox" checked={form.diaTodo} onChange={(e) => setForm({ ...form, diaTodo: e.target.checked })} style={{ accentColor: '#C39B99' }} />
                    Dia todo
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    <div className="flex flex-col gap-1">
                      <span className="mono text-[11px]" style={{ color: '#8C8478' }}>INÍCIO</span>
                      <input required type="date" value={form.dataInicio} onChange={(e) => setForm({ ...form, dataInicio: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                    </div>
                    <div className="flex flex-col gap-1">
                      <span className="mono text-[11px]" style={{ color: '#8C8478' }}>FIM</span>
                      <input type="date" value={form.dataFim} onChange={(e) => setForm({ ...form, dataFim: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                    </div>
                  </div>
                  {!form.diaTodo && (
                    <div className="grid grid-cols-2 gap-2">
                      <div className="flex flex-col gap-1">
                        <span className="mono text-[11px]" style={{ color: '#8C8478' }}>HORA INÍCIO</span>
                        <input required type="time" value={form.horaInicio} onChange={(e) => setForm({ ...form, horaInicio: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                      </div>
                      <div className="flex flex-col gap-1">
                        <span className="mono text-[11px]" style={{ color: '#8C8478' }}>HORA FIM</span>
                        <input required type="time" value={form.horaFim} onChange={(e) => setForm({ ...form, horaFim: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                      </div>
                    </div>
                  )}
                </>
              )}
              <button type="submit" className="focusable mono text-sm font-semibold rounded py-2 mt-1" style={{ background: '#C39B99', color: '#2B2724' }}>Adicionar</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

/* ---------- Tela: Financeiro ---------- */
function TelaFinanceiro({ financas, gastos, demandas, onCriarLancamento, onAtualizarLancamento, onAtualizarStatus, onExcluirLancamento, onCriarGasto, onExcluirGasto }) {
  const [subAba, setSubAba] = useState('receber');
  const [formAberto, setFormAberto] = useState(false);
  const [editandoLancamento, setEditandoLancamento] = useState(null);
  const [form, setForm] = useState(emptyFinanca);

  const resumo = useMemo(() => {
    const aReceber = financas.filter((f) => statusFinanceiro(f) !== 'pago').reduce((s, f) => s + (f.valorBruto ?? f.valor), 0);
    const recebido = financas.filter((f) => f.pago).reduce((s, f) => s + (f.valorBruto ?? f.valor), 0);
    const atrasado = financas.filter((f) => statusFinanceiro(f) === 'atrasado').reduce((s, f) => s + (f.valorBruto ?? f.valor), 0);
    return { aReceber, recebido, atrasado };
  }, [financas]);

  const [expandido, setExpandido] = useState(null);

  const lista = useMemo(() => {
    const grupos = {};
    financas.forEach((f) => {
      const chave = f.grupoParcelamento || `solo-${f.id}`;
      if (!grupos[chave]) grupos[chave] = [];
      grupos[chave].push(f);
    });
    const agrupados = Object.entries(grupos).map(([chave, itens]) => {
      const ordenados = [...itens].sort((a, b) => (a.parcelaNumero || 1) - (b.parcelaNumero || 1) || new Date(a.dataPagamento) - new Date(b.dataPagamento));
      const primeira = ordenados[0];
      const pagas = ordenados.filter((f) => f.pago).length;
      const todasPagas = pagas === ordenados.length;
      const algumAtrasado = ordenados.some((f) => !f.pago && statusFinanceiro(f) === 'atrasado');
      const statusGrupo = todasPagas ? 'pago' : (algumAtrasado ? 'atrasado' : 'pendente');
      const proximaNaoPaga = ordenados.find((f) => !f.pago);
      return {
        chave,
        cliente: primeira.cliente,
        projeto: primeira.projeto,
        dataTrabalho: primeira.dataTrabalho,
        itens: ordenados,
        parcelado: ordenados.length > 1,
        pagas,
        total: ordenados.length,
        statusGrupo,
        valorTotal: ordenados.reduce((s, f) => s + (f.valorBruto ?? f.valor), 0),
        comNF: primeira.comNF,
        dataReferencia: (proximaNaoPaga || ordenados[ordenados.length - 1]).dataPagamento,
      };
    });
    return agrupados
      .filter((g) => (subAba === 'concluidos' ? g.statusGrupo === 'pago' : g.statusGrupo !== 'pago'))
      .sort((a, b) => new Date(a.dataReferencia) - new Date(b.dataReferencia));
  }, [financas, subAba]);

  const dadosGrafico = useMemo(() => {
    const chaves = new Set();
    financas.forEach((f) => { if (f.pago) chaves.add(mesChave(f.dataPagamento)); });
    gastos.forEach((g) => chaves.add(mesChave(g.data)));
    return Array.from(chaves).sort().map((chave) => ({
      mes: mesLabelCurto(chave),
      entrada: financas.filter((f) => f.pago && mesChave(f.dataPagamento) === chave).reduce((s, f) => s + (f.valorBruto ?? f.valor), 0),
      saida: gastos.filter((g) => mesChave(g.data) === chave).reduce((s, g) => s + g.valor, 0),
    }));
  }, [financas, gastos]);

  async function mudarStatus(f, novoStatus) {
    await onAtualizarStatus(f, novoStatus === 'pago');
  }

  async function excluirLancamento(f) {
    const confirmar = window.confirm(`Excluir o lançamento de "${f.projeto}" (${f.cliente})? Essa ação não pode ser desfeita.`);
    if (!confirmar) return;
    await onExcluirLancamento(f);
  }

  function fecharForm() {
    setFormAberto(false);
    setEditandoLancamento(null);
    setForm(emptyFinanca);
  }

  function abrirEdicaoLancamento(g) {
    if (g.parcelado) {
      setForm({
        cliente: g.cliente,
        projeto: g.projeto,
        valor: String(g.valorTotal),
        dataTrabalho: g.dataTrabalho,
        dataPagamento: '',
        pago: false,
        parcelado: true,
        parcelas: g.itens.map((p) => ({ valor: p.valorBruto ?? p.valor, data: p.dataPagamento })),
      });
    } else {
      const item = g.itens[0];
      setForm({
        cliente: g.cliente,
        projeto: g.projeto,
        valor: String(item.valorBruto ?? item.valor),
        dataTrabalho: g.dataTrabalho,
        dataPagamento: item.dataPagamento,
        pago: item.pago,
        parcelado: false,
        parcelas: [],
      });
    }
    setEditandoLancamento(g);
    setFormAberto(true);
  }

  async function salvar(e) {
    e.preventDefault();
    if (!form.cliente || !form.projeto || !form.valor || !form.dataTrabalho) return;
    if (form.parcelado) {
      if (form.parcelas.length < 2 || form.parcelas.some((p) => !p.data || !p.valor)) return;
    } else if (!form.dataPagamento) {
      return;
    }
    if (editandoLancamento) await onAtualizarLancamento(editandoLancamento, form);
    else await onCriarLancamento(form);
    fecharForm();
  }

  return (
    <div>
      {subAba !== 'gastos' && (
        <div className="flex justify-end mb-4">
          <button onClick={() => { setEditandoLancamento(null); setForm(emptyFinanca); setFormAberto(true); }} className="focusable flex items-center gap-2 px-4 py-2 rounded mono text-sm font-semibold" style={{ background: '#C39B99', color: '#2B2724' }}>
            <Plus size={16} /> Novo lançamento
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        <div className="card rounded-lg p-4">
          <div className="mono text-xs tracking-widest mb-2" style={{ color: '#8C8478' }}>A RECEBER</div>
          <div className="mono text-2xl font-semibold" style={{ color: '#C39B99' }}>{moeda(resumo.aReceber)}</div>
        </div>
        <div className="card rounded-lg p-4">
          <div className="mono text-xs tracking-widest mb-2" style={{ color: '#8C8478' }}>RECEBIDO</div>
          <div className="mono text-2xl font-semibold" style={{ color: '#4C7A5E' }}>{moeda(resumo.recebido)}</div>
        </div>
        <div className="card rounded-lg p-4">
          <div className="mono text-xs tracking-widest mb-2" style={{ color: '#8C8478' }}>ATRASADO</div>
          <div className="mono text-2xl font-semibold" style={{ color: '#B4483D' }}>{moeda(resumo.atrasado)}</div>
        </div>
      </div>

      <div className="card rounded-lg p-4 md:p-5 mb-6">
        <div className="mono text-xs tracking-widest mb-3" style={{ color: '#8C8478' }}>ENTRADA X SAÍDA POR MÊS</div>
        {dadosGrafico.length === 0 ? (
          <p className="text-sm py-8 text-center" style={{ color: '#8C8478' }}>Sem dados suficientes ainda.</p>
        ) : (
          <div style={{ width: '100%', height: 260 }}>
            <ResponsiveContainer>
              <BarChart data={dadosGrafico} barGap={6}>
                <CartesianGrid strokeDasharray="3 3" stroke="#E8E3DC" vertical={false} />
                <XAxis dataKey="mes" stroke="#8C8478" tick={{ fill: '#8C8478', fontSize: 11, fontFamily: 'IBM Plex Mono' }} axisLine={{ stroke: '#E8E3DC' }} tickLine={false} />
                <YAxis stroke="#8C8478" tick={{ fill: '#8C8478', fontSize: 11, fontFamily: 'IBM Plex Mono' }} axisLine={{ stroke: '#E8E3DC' }} tickLine={false} tickFormatter={(v) => `${(v / 1000).toFixed(0)}k`} />
                <Tooltip
                  formatter={(v) => moeda(v)}
                  contentStyle={{ background: '#FFFFFF', border: '1px solid #E8E3DC', borderRadius: 6, fontFamily: 'Inter' }}
                  labelStyle={{ color: '#2B2724' }}
                  cursor={{ fill: 'rgba(255,255,255,0.03)' }}
                />
                <Legend wrapperStyle={{ fontFamily: 'IBM Plex Mono', fontSize: 11, color: '#8C8478' }} />
                <Bar dataKey="entrada" name="Entrada" fill="#4C7A5E" radius={[3, 3, 0, 0]} />
                <Bar dataKey="saida" name="Saída" fill="#B4483D" radius={[3, 3, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}
      </div>

      <div className="flex gap-1 p-1 rounded mb-4 w-fit" style={{ background: '#FFFFFF', border: '1px solid #E8E3DC' }}>
        {[{ key: 'receber', label: 'A receber' }, { key: 'concluidos', label: 'Concluídos' }, { key: 'gastos', label: 'Gastos' }].map((t) => (
          <button
            key={t.key}
            onClick={() => setSubAba(t.key)}
            className="focusable subtab px-4 py-1.5 rounded text-sm font-semibold"
            style={{ background: subAba === t.key ? '#C39B99' : 'transparent', color: subAba === t.key ? '#2B2724' : '#8C8478' }}
          >
            {t.label}
          </button>
        ))}
      </div>

      {subAba !== 'gastos' && (
        <div className="card rounded-lg overflow-hidden">
          {/* Cabeçalho — só desktop */}
          <div className="hidden sm:grid grid-cols-12 px-4 py-2 mono text-[11px] tracking-widest" style={{ color: '#8C8478', borderBottom: '1px solid #E8E3DC' }}>
            <div className="col-span-3">CLIENTE / PROJETO</div>
            <div className="col-span-2">TRABALHO</div>
            <div className="col-span-2">PAGAMENTO</div>
            <div className="col-span-2 text-right">VALOR</div>
            <div className="col-span-2 text-right">STATUS</div>
            <div className="col-span-1 text-right"></div>
          </div>

          {lista.map((g) => {
            const s = STATUS_FIN[g.statusGrupo];
            const aberto = expandido === g.chave;
            const statusLabel = g.parcelado ? `${g.pagas}/${g.total} PARCELAS` : s.label.toUpperCase();
            return (
              <div key={g.chave}>
                {/* Card — só celular */}
                <div className="sm:hidden flex flex-col gap-2 px-4 py-3" style={{ borderBottom: '1px solid #EFEAE3' }}>
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="text-sm font-semibold">{g.cliente}</div>
                      <div className="text-xs" style={{ color: '#8C8478' }}>{g.projeto}{g.parcelado && ` · ${g.total}x`}</div>
                    </div>
                    <div className="flex items-center gap-3 flex-shrink-0">
                      <button onClick={() => abrirEdicaoLancamento(g)} className="focusable" title="Editar lançamento" style={{ color: '#8C8478' }}>
                        <Pencil size={14} />
                      </button>
                      <button onClick={() => excluirLancamento(g.itens[0])} className="focusable" title={g.parcelado ? 'Excluir todas as parcelas' : 'Excluir lançamento'} style={{ color: '#8C8478' }}>
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </div>
                  <div className="flex items-center justify-between">
                    <div>
                      <div className="mono text-sm">{moeda(g.valorTotal)}</div>
                      {g.comNF && <div className="mono text-[10px]" style={{ color: '#8C8478' }}>com NF</div>}
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="mono text-[11px] font-semibold px-2 py-1 rounded" style={{ color: s.color, background: `${s.color}1F`, border: `1px solid ${s.color}55` }}>{statusLabel}</span>
                      <a
                        href={URL_EMISSOR_NF}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="focusable flex items-center gap-1 rounded px-2 py-1 mono text-[10px] font-semibold"
                        style={{ background: 'transparent', border: '1px solid #E8E3DC', color: '#8C8478' }}
                      >
                        <Receipt size={12} /> NF
                      </a>
                    </div>
                  </div>
                  {g.parcelado ? (
                    <button onClick={() => setExpandido(aberto ? null : g.chave)} className="focusable flex items-center justify-between mono text-xs" style={{ color: '#8C8478' }}>
                      Ver parcelas <ChevronDown size={14} style={{ transform: aberto ? 'rotate(180deg)' : 'none' }} />
                    </button>
                  ) : (
                    <div className="flex justify-between mono text-xs" style={{ color: '#8C8478' }}>
                      <span>Trabalho: {new Date(g.dataTrabalho + 'T00:00:00').toLocaleDateString('pt-BR')}</span>
                      <span>Pagto: {new Date(g.itens[0].dataPagamento + 'T00:00:00').toLocaleDateString('pt-BR')}</span>
                    </div>
                  )}
                  {aberto && g.parcelado && (
                    <div className="flex flex-col gap-2 mt-1 pt-2" style={{ borderTop: '1px solid #EFEAE3' }}>
                      {g.itens.map((p) => {
                        const sp = STATUS_FIN[statusFinanceiro(p)];
                        return (
                          <div key={p.id} className="flex items-center justify-between">
                            <div>
                              <div className="mono text-xs">Parcela {p.parcelaNumero}/{p.parcelaTotal}</div>
                              <div className="mono text-[10px]" style={{ color: '#8C8478' }}>{new Date(p.dataPagamento + 'T00:00:00').toLocaleDateString('pt-BR')} · {moeda(p.valorBruto ?? p.valor)}</div>
                            </div>
                            <label className="flex items-center gap-1.5 mono text-xs cursor-pointer" style={{ color: sp.color }}>
                              <input type="checkbox" checked={p.pago} onChange={(e) => mudarStatus(p, e.target.checked ? 'pago' : 'pendente')} style={{ accentColor: '#4C7A5E' }} />
                              {p.parcelaNumero}º pgt
                            </label>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>

                {/* Linha de tabela — só desktop */}
                <div className="hidden sm:grid grid-cols-12 px-4 py-3 items-center" style={{ borderBottom: '1px solid #EFEAE3' }}>
                  <div className="col-span-3">
                    <div className="text-sm font-semibold">{g.cliente}</div>
                    <div className="text-xs" style={{ color: '#8C8478' }}>{g.projeto}{g.parcelado && ` · ${g.total}x`}</div>
                  </div>
                  <div className="col-span-2 mono text-sm" style={{ color: '#8C8478' }}>{new Date(g.dataTrabalho + 'T00:00:00').toLocaleDateString('pt-BR')}</div>
                  <div className="col-span-2 mono text-sm" style={{ color: '#8C8478' }}>
                    {g.parcelado ? (
                      <button onClick={() => setExpandido(aberto ? null : g.chave)} className="focusable flex items-center gap-1" style={{ color: '#8C8478' }}>
                        {g.total} parcelas <ChevronDown size={12} style={{ transform: aberto ? 'rotate(180deg)' : 'none' }} />
                      </button>
                    ) : (
                      new Date(g.itens[0].dataPagamento + 'T00:00:00').toLocaleDateString('pt-BR')
                    )}
                  </div>
                  <div className="col-span-2 text-right">
                    <div className="mono text-sm">{moeda(g.valorTotal)}</div>
                    {g.comNF && <div className="mono text-[10px]" style={{ color: '#8C8478' }}>com NF</div>}
                  </div>
                  <div className="col-span-2 flex flex-wrap justify-end items-center gap-2">
                    <span className="mono text-[11px] font-semibold px-2 py-1 rounded" style={{ color: s.color, background: `${s.color}1F`, border: `1px solid ${s.color}55` }}>{statusLabel}</span>
                    {!g.parcelado && (
                      <label className="flex items-center gap-1.5 mono text-xs cursor-pointer" style={{ color: s.color }}>
                        <input type="checkbox" checked={g.itens[0].pago} onChange={(e) => mudarStatus(g.itens[0], e.target.checked ? 'pago' : 'pendente')} style={{ accentColor: '#4C7A5E' }} />
                        Pago
                      </label>
                    )}
                    <a
                      href={URL_EMISSOR_NF}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="focusable flex items-center gap-1.5 rounded px-2 py-1 mono text-[11px] font-semibold"
                      style={{ background: 'transparent', border: '1px solid #E8E3DC', color: '#8C8478' }}
                    >
                      <Receipt size={12} /> EMITIR NF
                    </a>
                  </div>
                  <div className="col-span-1 flex justify-end gap-2">
                    <button onClick={() => abrirEdicaoLancamento(g)} className="focusable" title="Editar lançamento" style={{ color: '#8C8478' }}>
                      <Pencil size={14} />
                    </button>
                    <button onClick={() => excluirLancamento(g.itens[0])} className="focusable" title={g.parcelado ? 'Excluir todas as parcelas' : 'Excluir lançamento'} style={{ color: '#8C8478' }}>
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>
                {aberto && g.parcelado && (
                  <div className="hidden sm:block px-4 pb-3" style={{ borderBottom: '1px solid #EFEAE3', background: 'rgba(255,255,255,0.02)' }}>
                    {g.itens.map((p) => {
                      const sp = STATUS_FIN[statusFinanceiro(p)];
                      return (
                        <div key={p.id} className="grid grid-cols-12 py-2 items-center">
                          <div className="col-span-3 mono text-xs" style={{ color: '#8C8478' }}>Parcela {p.parcelaNumero}/{p.parcelaTotal}</div>
                          <div className="col-span-4 mono text-xs" style={{ color: '#8C8478' }}>{new Date(p.dataPagamento + 'T00:00:00').toLocaleDateString('pt-BR')}</div>
                          <div className="col-span-2 mono text-xs text-right">{moeda(p.valorBruto ?? p.valor)}</div>
                          <div className="col-span-3 flex justify-end">
                            <label className="flex items-center gap-1.5 mono text-xs cursor-pointer" style={{ color: sp.color }}>
                              <input type="checkbox" checked={p.pago} onChange={(e) => mudarStatus(p, e.target.checked ? 'pago' : 'pendente')} style={{ accentColor: '#4C7A5E' }} />
                              {p.parcelaNumero}º pgt
                            </label>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}
          {lista.length === 0 && <div className="text-center py-10 mono text-sm" style={{ color: '#8C8478' }}>Nada por aqui ainda.</div>}
        </div>
      )}

      {subAba === 'gastos' && <TelaGastos gastos={gastos} financas={financas} demandas={demandas} onCriar={onCriarGasto} onExcluir={onExcluirGasto} />}

      {formAberto && (
        <div className="fixed inset-0 flex items-start sm:items-center justify-center p-4 overflow-y-auto py-8" style={{ background: 'rgba(0,0,0,0.6)' }}>
          <form onSubmit={salvar} className="card rounded-lg p-6 w-full max-w-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="mono text-sm tracking-widest" style={{ color: '#8C8478' }}>{editandoLancamento ? 'EDITAR LANÇAMENTO' : 'NOVO LANÇAMENTO'}</h2>
              <button type="button" onClick={fecharForm} className="focusable" aria-label="Fechar"><X size={18} color="#8C8478" /></button>
            </div>
            <div className="flex flex-col gap-3">
              <input required placeholder="Cliente" value={form.cliente} onChange={(e) => setForm({ ...form, cliente: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required placeholder="Projeto" value={form.projeto} onChange={(e) => setForm({ ...form, projeto: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required type="number" placeholder="Valor total (R$)" value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <div className="flex flex-col gap-1">
                <span className="mono text-[11px]" style={{ color: '#8C8478' }}>DATA DO TRABALHO</span>
                <input required type="date" value={form.dataTrabalho} onChange={(e) => setForm({ ...form, dataTrabalho: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              </div>

              <CamposParcelamento form={form} setForm={setForm} />

              {!form.parcelado && (
                <>
                  <div className="flex flex-col gap-1">
                    <span className="mono text-[11px]" style={{ color: '#8C8478' }}>DATA DO PAGAMENTO</span>
                    <input required type="date" value={form.dataPagamento} onChange={(e) => setForm({ ...form, dataPagamento: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
                  </div>
                  <label className="flex items-center gap-2 text-sm mono" style={{ color: '#8C8478' }}>
                    <input type="checkbox" checked={form.pago} onChange={(e) => setForm({ ...form, pago: e.target.checked })} style={{ accentColor: '#C39B99' }} />
                    Já recebido
                  </label>
                </>
              )}

              <button type="submit" className="focusable mono text-sm font-semibold rounded py-2 mt-1" style={{ background: '#C39B99', color: '#2B2724' }}>{editandoLancamento ? 'Salvar alterações' : 'Adicionar'}</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

/* ---------- Tela: Gastos ---------- */
function TelaGastos({ gastos, financas, demandas, onCriar, onExcluir }) {
  const [formAberto, setFormAberto] = useState(false);
  const [form, setForm] = useState(emptyGasto);

  const projetosDisponiveis = useMemo(() => {
    const map = {};
    financas.forEach((f) => { map[f.projeto] = f.cliente; });
    demandas.forEach((d) => { if (!map[d.projeto]) map[d.projeto] = d.cliente; });
    return Object.entries(map).map(([projeto, cliente]) => ({ projeto, cliente }));
  }, [financas, demandas]);

  const grupos = useMemo(() => {
    const projetos = new Set([...financas.map((f) => f.projeto), ...gastos.map((g) => g.projeto)]);
    return Array.from(projetos).map((projeto) => {
      const financasDoProjeto = financas.filter((f) => f.projeto === projeto);
      const cliente = financasDoProjeto[0]?.cliente || gastos.find((g) => g.projeto === projeto)?.cliente || '—';
      const valorProjeto = financasDoProjeto.reduce((s, f) => s + (f.valorBruto ?? f.valor), 0);
      const valorLiquido = financasDoProjeto.reduce((s, f) => s + f.valor, 0);
      const temNF = financasDoProjeto.some((f) => f.comNF);
      const itens = gastos.filter((g) => g.projeto === projeto);
      const totalGastos = itens.reduce((s, g) => s + g.valor, 0);
      return { projeto, cliente, valorProjeto, valorLiquido, temNF, itens, totalGastos, lucro: valorLiquido - totalGastos };
    }).filter((g) => g.valorProjeto > 0 || g.itens.length > 0);
  }, [financas, gastos]);

  async function adicionar(e) {
    e.preventDefault();
    if (!form.projeto || !form.descricao || !form.valor || !form.data) return;
    const cliente = projetosDisponiveis.find((p) => p.projeto === form.projeto)?.cliente || form.cliente;
    await onCriar({ ...form, cliente });
    setForm(emptyGasto);
    setFormAberto(false);
  }

  async function excluirGasto(item) {
    const confirmar = window.confirm(`Excluir o gasto "${item.descricao}"? Essa ação não pode ser desfeita.`);
    if (!confirmar) return;
    await onExcluir(item);
  }

  return (
    <div>
      <div className="flex justify-end mb-4">
        <button onClick={() => setFormAberto(true)} className="focusable flex items-center gap-2 px-4 py-2 rounded mono text-sm font-semibold" style={{ background: '#C39B99', color: '#2B2724' }}>
          <Plus size={16} /> Novo gasto
        </button>
      </div>

      <div className="flex flex-col gap-4">
        {grupos.map((g) => (
          <div key={g.projeto} className="card rounded-lg p-4 md:p-5">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4">
              <div>
                <div className="text-xs" style={{ color: '#8C8478' }}>{g.cliente}</div>
                <div className="flex items-center gap-2">
                  <h3 className="font-semibold text-base">{g.projeto}</h3>
                  {g.temNF && (
                    <span
                      className="mono text-[9px] font-semibold px-1.5 py-0.5 rounded"
                      style={{ color: '#A89B8C', background: '#A89B8C1F', border: '1px solid #8A8F9555' }}
                    >
                      COM NF
                    </span>
                  )}
                </div>
              </div>
              <div className="grid grid-cols-3 gap-2 sm:gap-5 sm:flex">
                <div>
                  <div className="mono text-[10px] tracking-widest" style={{ color: '#8C8478' }}>SERVIÇO</div>
                  <div className="mono text-xs sm:text-sm font-semibold" style={{ color: '#C39B99' }}>{moeda(g.valorProjeto)}</div>
                  {g.temNF && <div className="mono text-[10px]" style={{ color: '#8C8478' }}>líq. {moeda(g.valorLiquido)}</div>}
                </div>
                <div>
                  <div className="mono text-[10px] tracking-widest" style={{ color: '#8C8478' }}>GASTOS</div>
                  <div className="mono text-xs sm:text-sm font-semibold" style={{ color: '#B4483D' }}>{moeda(g.totalGastos)}</div>
                </div>
                <div>
                  <div className="mono text-[10px] tracking-widest" style={{ color: '#8C8478' }}>LUCRO</div>
                  <div className="mono text-xs sm:text-sm font-semibold" style={{ color: g.lucro >= 0 ? '#4C7A5E' : '#B4483D' }}>{moeda(g.lucro)}</div>
                </div>
              </div>
            </div>

            {g.itens.length > 0 && (
              <div className="flex flex-col gap-2">
                {g.itens.map((item) => (
                  <div key={item.id} className="flex items-center justify-between gap-3 py-2" style={{ borderTop: '1px solid #EFEAE3' }}>
                    <div className="text-sm" style={{ color: '#2B2724' }}>{item.descricao}</div>
                    <div className="flex items-center gap-3 flex-shrink-0">
                      <span className="mono text-xs" style={{ color: '#8C8478' }}>{moeda(item.valor)}</span>
                      <button onClick={() => excluirGasto(item)} className="focusable" title="Excluir gasto" style={{ color: '#8C8478' }}>
                        <Trash2 size={13} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
            {g.itens.length === 0 && <p className="text-xs" style={{ color: '#8C8478' }}>Nenhum gasto lançado ainda.</p>}
          </div>
        ))}
        {grupos.length === 0 && <div className="card rounded-lg text-center py-12 mono text-sm" style={{ color: '#8C8478' }}>Nenhum projeto com dados financeiros ainda.</div>}
      </div>

      {formAberto && (
        <div className="fixed inset-0 flex items-start sm:items-center justify-center p-4 overflow-y-auto py-8" style={{ background: 'rgba(0,0,0,0.6)' }}>
          <form onSubmit={adicionar} className="card rounded-lg p-6 w-full max-w-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="mono text-sm tracking-widest" style={{ color: '#8C8478' }}>NOVO GASTO</h2>
              <button type="button" onClick={() => setFormAberto(false)} className="focusable" aria-label="Fechar"><X size={18} color="#8C8478" /></button>
            </div>
            <div className="flex flex-col gap-3">
              <select required value={form.projeto} onChange={(e) => setForm({ ...form, projeto: e.target.value })} className="focusable rounded px-3 py-2 text-sm">
                <option value="">Selecione o projeto</option>
                {projetosDisponiveis.map((p) => <option key={p.projeto} value={p.projeto}>{p.projeto} — {p.cliente}</option>)}
              </select>
              <input required placeholder="Descrição (ex: freelancer, aluguel de equipamento)" value={form.descricao} onChange={(e) => setForm({ ...form, descricao: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required type="number" placeholder="Valor (R$)" value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <input required type="date" value={form.data} onChange={(e) => setForm({ ...form, data: e.target.value })} className="focusable rounded px-3 py-2 text-sm" />
              <button type="submit" className="focusable mono text-sm font-semibold rounded py-2 mt-1" style={{ background: '#C39B99', color: '#2B2724' }}>Adicionar</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}
